    var M016 = `
CREATE TABLE cb_binding_merges (
  absorbed_id       TEXT PRIMARY KEY,
  winner_id         TEXT NOT NULL REFERENCES cb_bindings(id),
  owner_before      TEXT NOT NULL,
  host_install      TEXT NOT NULL,
  conversation_ref  TEXT NOT NULL,
  state_before      TEXT NOT NULL,
  project_id_before TEXT,
  merged_at         TEXT NOT NULL
);

CREATE TEMP TABLE _afetados AS
SELECT id, owner, host_install, conversation_ref, state, project_id,
       COALESCE(last_seen_at, updated_at, created_at) AS quando
FROM cb_bindings
WHERE owner IN (SELECT 'sujeito:' || id FROM sessions)
   OR owner LIKE 'sujeito:ses\\_%' ESCAPE '\\';

-- Vencedora por trio: ativa vence suspensa vence revogada; com projeto vence
-- sem projeto; mais recente vence; e o id desempata, para ser determin\xEDstica.
CREATE TEMP TABLE _vencedoras AS
SELECT host_install, conversation_ref, (
  SELECT a.id FROM _afetados a
  WHERE a.host_install = g.host_install AND a.conversation_ref = g.conversation_ref
  ORDER BY CASE a.state WHEN 'active' THEN 0 WHEN 'suspended' THEN 1 ELSE 2 END,
           CASE WHEN a.project_id IS NULL THEN 1 ELSE 0 END,
           a.quando DESC,
           a.id
  LIMIT 1
) AS winner_id
FROM _afetados g
GROUP BY g.host_install, g.conversation_ref;

INSERT INTO cb_binding_merges (absorbed_id, winner_id, owner_before, host_install, conversation_ref, state_before, project_id_before, merged_at)
SELECT a.id, v.winner_id, a.owner, a.host_install, a.conversation_ref, a.state, a.project_id,
       (SELECT COALESCE(MAX(updated_at), MAX(created_at), '1970-01-01T00:00:00.000Z') FROM cb_bindings)
FROM _afetados a
JOIN _vencedoras v ON v.host_install = a.host_install AND v.conversation_ref = a.conversation_ref
WHERE a.id <> v.winner_id;

UPDATE cb_snapshots
SET binding_id = (SELECT m.winner_id FROM cb_binding_merges m WHERE m.absorbed_id = cb_snapshots.binding_id)
WHERE binding_id IN (SELECT absorbed_id FROM cb_binding_merges);

DELETE FROM cb_bindings WHERE id IN (SELECT absorbed_id FROM cb_binding_merges);

UPDATE cb_bindings
SET owner = (SELECT value FROM schema_meta WHERE key = 'profile_owner')
WHERE id IN (SELECT id FROM _afetados);

UPDATE cb_snapshots
SET owner = (SELECT value FROM schema_meta WHERE key = 'profile_owner')
WHERE binding_id IN (SELECT id FROM cb_bindings);

-- Duas s\xE9ries de vers\xF5es somadas repetiriam n\xFAmeros: renumera por v\xEDnculo onde
-- houve absor\xE7\xE3o. Sem window function, por portabilidade.
UPDATE cb_snapshots
SET version = (
  SELECT COUNT(*) FROM cb_snapshots x
  WHERE x.binding_id = cb_snapshots.binding_id
    AND (x.created_at < cb_snapshots.created_at
         OR (x.created_at = cb_snapshots.created_at AND x.id <= cb_snapshots.id))
)
WHERE binding_id IN (SELECT winner_id FROM cb_binding_merges);

DROP TABLE _vencedoras;
DROP TABLE _afetados;
`;
